def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line - add the last field if we're not at the very start
            # (empty line case is handled by returning [''])
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check that it's followed by comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        # Skip the comma if present
                        if i < n and line[i] == ',':
                            i += 1
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Quote in unquoted field is malformed
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            # Skip the comma if present
            if i < n and line[i] == ',':
                i += 1

    # Handle empty line case
    if not fields:
        return ['']

    return fields

